INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (1, 'SMT Line', 'ESD', FALSE, 'ESD監控系統是否正常運行？', 'Is the ESD monitoring system operating properly?', 'ระบบตรวจสอบ ESD ทำงานเป็นปกติหรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (2, 'SMT Line', 'SMT-General', FALSE, '所有設備是否接地並貼附 ESD 標識標籤？', 'Are all equipment properly grounded and labeled with ESD identification labels?', 'อุปกรณ์ทั้งหมดมีการต่อสายดินและติดฉลากระบุ ESD หรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (3, 'SMT Line', 'SMT-General', FALSE, '各站人員是否有穿靜電衣、靜電鞋、戴靜電帽、靜電環、靜電手套作業？', 'Are operators at each station wearing ESD garments, ESD shoes, ESD caps, ESD wrist straps, and ESD gloves during operation?', 'พนักงานในแต่ละสถานีสวมชุดป้องกันไฟฟ้าสถิต รองเท้า ESD หมวก ESD สายรัดข้อมือ ESD และถุงมือ ESD ระหว่างปฏิบัติงานหรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (4, 'SMT Line', 'SMT-General', FALSE, '台面、台桌、靜電椅、靜電架是否有接地？', 'Are the workbench, workstation, ESD chair, and ESD rack properly grounded?', 'โต๊ะทำงาน พื้นที่ปฏิบัติงาน เก้าอี้ ESD และชั้นวาง ESD มีการต่อสายดินหรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (5, 'SMT Line', 'SMT-General', FALSE, 'ESD 日常點檢是否有記錄？', 'Are daily ESD inspection records maintained?', 'มีการบันทึกผลการตรวจสอบ ESD ประจำวันหรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (6, 'SMT Line', 'FAI', FALSE, '檢查所有材料是否與 BOM 相符。', 'Check whether all materials match the BOM.', 'ตรวจสอบว่าวัสดุทั้งหมดตรงตาม BOM หรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (7, 'SMT Line', 'SMT-General', FALSE, '首件檢驗元件方向、極性及位置是否與圖紙相符？', 'Do the component orientation, polarity, and location of the first article conform to the drawing?', 'ทิศทาง ขั้ว และตำแหน่งของชิ้นส่วนในการตรวจสอบชิ้นงานแรกตรงตามแบบหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (8, 'SMT Line', 'SMT-General', FALSE, '檢查 PCBA 焊接外觀是否符合 IPC 標準。', 'Check whether the PCBA soldering appearance complies with IPC standards.', 'ตรวจสอบว่าลักษณะงานบัดกรีของ PCBA เป็นไปตามมาตรฐาน IPC หรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (9, 'SMT Line', 'SMT-General', FALSE, '條碼是否符合編碼規則？', 'Does the barcode comply with the coding rules?', 'บาร์โค้ดเป็นไปตามข้อกำหนดการเข้ารหัสหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (10, 'SMT Line', 'SMT-General', FALSE, '首件完成後是否貼附綠色 OK 標籤並放置於產線指定區域？', 'After first article inspection, is the green OK label attached and the product placed in the designated production line area?', 'หลังตรวจสอบชิ้นงานแรกเสร็จ มีการติดฉลากสีเขียว OK และวางไว้ในพื้นที่ที่กำหนดของสายการผลิตหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (11, 'SMT Line', 'SMT-General', FALSE, '新機種與 ECN 變更機種試產首件是否使用膠紙板？', 'Is a backing board used for the first trial production of new models and ECN-changed models?', 'ชิ้นงานแรกของการทดลองผลิตสำหรับรุ่นใหม่และรุ่นที่มีการเปลี่ยนแปลงตาม ECN ใช้แผ่นรองกระดาษกาวหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (12, 'SMT Line', 'SMT-General', FALSE, '是否依 ECN 要求執行？ECN 編號：______', 'Is the implementation carried out according to the ECN requirements? ECN No.: ______', 'มีการดำเนินการตามข้อกำหนดของ ECN หรือไม่ หมายเลข ECN: ______') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (13, 'SMT Line', 'SMT-General', FALSE, '每站是否懸掛 SOP（正式文件必須蓋章，臨時文件必須有 IE 簽名）？', 'Is the SOP posted at each station (official documents must bear an approval stamp; temporary documents must be signed by IE)?', 'แต่ละสถานีมีการแสดง SOP หรือไม่ (เอกสารทางการต้องมีตราประทับ และเอกสารชั่วคราวต้องมีลายเซ็นของ IE)') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (14, 'SMT Line', 'SMT-General', FALSE, 'PMP 是否與工程標準參數、機種、版本及 SOP 相符？', 'Does the PMP conform to the engineering standard parameters, model, version, and SOP?', 'PMP สอดคล้องกับพารามิเตอร์มาตรฐานทางวิศวกรรม รุ่น เวอร์ชัน และ SOP หรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (15, 'SMT Line', 'SMT-General', TRUE, '車間溫、濕度是否在規定範圍內（20°C–28°C，30%RH–60%RH）？', 'Are the workshop temperature and humidity within the specified range (20°C–28°C, 30%RH–60%RH)?', 'อุณหภูมิและความชื้นในพื้นที่การผลิตอยู่ภายในช่วงที่กำหนด (20°C–28°C, 30%RH–60%RH) หรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (16, 'SMT Line', 'SMT-Mounter', FALSE, '貼片載具變形量是否＜0.4 mm？', 'Is the SMT fixture deformation less than 0.4 mm?', 'ค่าการเสียรูปของฟิกซ์เจอร์ SMT น้อยกว่า 0.4 มม. หรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (17, 'SMT Line', 'SMT-General', FALSE, 'PCB 放入托盤治具內是否與鋼板治具完全吻合？', 'Does the PCB fit completely into the tray fixture and match the stencil fixture correctly?', 'PCB ที่วางในถาดฟิกซ์เจอร์เข้าพอดีกับฟิกซ์เจอร์สเตนซิล (Steel Stencil Fixture) อย่างสมบูรณ์หรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (18, 'SMT Line', 'SMT-Printer', FALSE, '印刷機程式名稱與版本是否正確；刮刀壓力、速度及擦拭設定是否與 SOP 參數設定表一致？', 'Are the printer program name and version correct? Are the squeegee pressure, speed, and cleaning settings consistent with the SOP parameter setting sheet?', 'ชื่อโปรแกรมและเวอร์ชันของเครื่องพิมพ์ถูกต้องหรือไม่ และการตั้งค่าแรงกด ความเร็วของสกวีจี และการเช็ดทำความสะอาดสอดคล้องกับตารางการตั้งค่าพารามิเตอร์ใน SOP หรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (19, 'SMT Line', 'SMT-Printer', FALSE, '鋼網張力測試參數是否符合 SOP 要求（35–65 N），並有記錄於表單？', 'Do the stencil tension test parameters comply with the SOP requirements (35–65 N), and are they recorded on the inspection form?', 'ค่าความตึงของสเตนซิลเป็นไปตามข้อกำหนดของ SOP (35–65 N) และมีการบันทึกไว้ในแบบฟอร์มหรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (20, 'SMT Line', 'SMT-Printer', TRUE, '錫膏（膠）型號與有效日期。', 'Solder Paste (Adhesive) Model and Expiration Date.', 'รุ่นของครีมบัดกรี (หรือกาว) และวันหมดอายุ') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (21, 'SMT Line', 'SMT-Printer', TRUE, '錫膏（膠）儲存溫度（參考 SOP）是多少？', 'What is the storage temperature for the solder paste (adhesive) according to the SOP?', 'อุณหภูมิในการจัดเก็บครีมบัดกรี (หรือกาว) ตาม SOP คือเท่าใด?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (22, 'SMT Line', 'SMT-Printer', FALSE, '錫膏從冰箱取出時，是否填寫回溫時間、開封時間及未使用完的報廢時間？攪拌方法是否與 SOP 一致？', 'When the solder paste is taken out of the refrigerator, are the warm-up time, opening time, and disposal time for unused paste recorded? Is the mixing method consistent with the SOP?', 'เมื่อนำครีมบัดกรีออกจากตู้เย็น มีการบันทึกเวลาปรับอุณหภูมิ เวลาเปิดใช้งาน และเวลาทิ้งกรณีใช้ไม่หมดหรือไม่ และวิธีการกวนครีมบัดกรีเป็นไปตาม SOP หรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (23, 'SMT Line', 'SMT-Printer', FALSE, '錫膏、膠領用是否有記錄？', 'Are solder paste and adhesive issuance records maintained?', 'มีการบันทึกการเบิกใช้ครีมบัดกรีและกาวหรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (24, 'SMT Line', 'SMT-Printer', TRUE, '錫膏厚度是否及時記錄？確認錫膏厚度是否符合要求，若超出是否有改善措施？', 'Is the solder paste thickness recorded in a timely manner? Does the thickness meet the specification, and if it is out of specification, are corrective actions taken?', 'มีการบันทึกความหนาของครีมบัดกรีอย่างทันท่วงทีหรือไม่ ความหนาเป็นไปตามข้อกำหนดหรือไม่ และหากเกินข้อกำหนดมีมาตรการแก้ไขหรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (25, 'SMT Line', 'SMT-Printer', FALSE, '印刷站蜂鳴器是否每 30 分鐘正常警報？員工是否每 30 分鐘手動收集一次錫膏並有記錄？', 'Does the printer station buzzer alarm every 30 minutes as required? Do operators manually collect solder paste every 30 minutes and keep records?', 'สัญญาณเตือนของสถานีพิมพ์ทำงานทุก 30 นาทีตามปกติหรือไม่ และพนักงานมีการเก็บครีมบัดกรีด้วยตนเองทุก 30 นาทีพร้อมบันทึกข้อมูลหรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (26, 'SMT Line', 'SMT-Printer', TRUE, '錫膏印刷是否有短路、偏移或少錫（偏移、少錫＜25%）？', 'Is the solder paste printing free from bridging, misalignment, and insufficient solder (misalignment and insufficient solder <25%)?', 'งานพิมพ์ครีมบัดกรีไม่มีปัญหาการลัดวงจร การเยื้องตำแหน่ง หรือครีมบัดกรีไม่เพียงพอ (การเยื้องและครีมบัดกรีไม่เพียงพอต้องน้อยกว่า 25%) หรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (27, 'SMT Line', 'SMT-Mounter', FALSE, '貼片機程式名稱與版本是否正確？', 'Is the placement machine program name and version correct?', 'ชื่อโปรแกรมและเวอร์ชันของเครื่องวางชิ้นส่วน (SMT Placement Machine) ถูกต้องหรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (28, 'SMT Line', 'SMT-General', TRUE, '元件是否偏移 PAD？是否有錯件、漏件、反向、損件或線路損傷？', 'Are there any components shifted from the PAD? Are there any wrong parts, missing parts, reversed parts, damaged parts, or circuit damage?', 'ชิ้นส่วนมีการเยื้องจาก PAD หรือไม่ มีการใส่ชิ้นส่วนผิด ขาด ใส่กลับด้าน ชิ้นส่วนเสียหาย หรือแผงวงจรเสียหายหรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (29, 'SMT Line', 'SMT-General', TRUE, '是否有翹起、立碑、翻面、多件、短路、側碑等不良？', 'Are there any defects such as lifted components, tombstoning, flipped components, extra components, short circuits, or side tombstoning?', 'มีข้อบกพร่อง เช่น ชิ้นส่วนยกตัว (Lifted), Tombstone, กลับด้าน, ใส่เกิน, ลัดวงจร หรือ Side Tombstone หรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (30, 'SMT Line', 'SMT-General', FALSE, '材料是否依料序表裝入機台對應站位？', 'Are the materials loaded into the correct machine feeder positions according to the material loading list?', 'วัสดุถูกติดตั้งในตำแหน่งของเครื่องตามรายการลำดับวัสดุหรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (31, 'SMT Line', 'SMT-General', FALSE, '材料區尾料是否有材料料號、條碼、規格、簽名等？', 'Do the remaining materials in the material area have material part number, barcode, specification, and signature identification?', 'วัสดุคงเหลือในพื้นที่จัดเก็บมีหมายเลขวัสดุ บาร์โค้ด สเปก และลายเซ็นกำกับครบถ้วนหรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (32, 'SMT Line', 'SMT-General', FALSE, '產線換料是否有做記錄？', 'Are material replacement records maintained on the production line?', 'มีการบันทึกการเปลี่ยนวัสดุในสายการผลิตหรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (33, 'SMT Line', 'SMT-Reflow', FALSE, '是否按 SOP 使用氮氣？', 'Is nitrogen used in accordance with the SOP?', 'มีการใช้ก๊าซไนโตรเจนตาม SOP หรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (34, 'SMT Line', 'SMT-General', FALSE, '盤裝 IC 有無混料、反向，打件方向是否正確？', 'Are tray-packed ICs free from mixed materials and reversed orientation, and is the placement direction correct?', 'IC แบบถาดไม่มีการปะปนวัสดุหรือกลับด้าน และทิศทางการวางถูกต้องหรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (35, 'SMT Line', 'SMT-General', FALSE, '需烘烤的 PCB 及材料是否依標準記錄？', 'Are the baking records for PCBs and materials maintained according to the standard?', 'PCB และวัสดุที่ต้องอบ มีการบันทึกตามมาตรฐานหรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (36, 'SMT Line', 'SMT-General', FALSE, '需放入乾燥櫃的 PCB/FPCB 和材料是否有送入與取出記錄？', 'Are there records for placing and removing PCBs/FPCBs and materials from the dry cabinet?', 'PCB/FPCB และวัสดุที่ต้องเก็บในตู้ควบคุมความชื้น มีบันทึกการนำเข้าและนำออกหรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (37, 'SMT Line', 'SMT-General', FALSE, '稽核產線禁止手擺 CHIP 元件。', 'Verify that manual placement of CHIP components is prohibited on the production line.', 'ตรวจสอบว่าสายการผลิตไม่มีการวางชิ้นส่วน CHIP ด้วยมือ') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (38, 'SMT Line', 'SMT-General', FALSE, '手擺料是否有區分、標示、記錄且單獨送檢？', 'Are manually placed materials identified, labeled, recorded, and submitted for inspection separately?', 'วัสดุที่วางด้วยมือมีการแยกประเภท ติดฉลาก บันทึก และส่งตรวจแยกต่างหากหรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (39, 'SMT Line', 'SMT-General', FALSE, '輔耗材是否貼有 Green/HF 標示？', 'Are auxiliary materials labeled with Green/HF identification?', 'วัสดุสิ้นเปลืองมีฉลาก Green/HF หรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (40, 'SMT Line', 'SMT-General', FALSE, '溫濕敏元件開封時是否有貼溫濕敏元件跟蹤標籤？', 'Is a moisture-sensitive device (MSD) tracking label attached when the package is opened?', 'เมื่อเปิดบรรจุภัณฑ์ของชิ้นส่วนไวต่ออุณหภูมิและความชื้น (MSD) มีการติดฉลากติดตามหรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (41, 'SMT Line', 'SMT-General', FALSE, '溫濕敏元件開封後使用是否在有效時間內，未使用完是否按溫濕敏元件 SOP 管控？', 'Are moisture-sensitive devices used within the allowable exposure time after opening, and are unused components controlled according to the MSD SOP?', 'หลังเปิดบรรจุภัณฑ์ ชิ้นส่วน MSD ถูกใช้งานภายในเวลาที่กำหนดหรือไม่ และชิ้นส่วนที่ใช้ไม่หมดได้รับการควบคุมตาม SOP ของ MSD หรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (42, 'SMT Line', 'SMT-General', FALSE, '溫濕敏元件超過有效保存期時是否有烘烤，並符合 SOP 規定要求？', 'Are moisture-sensitive devices baked after exceeding the allowable storage period, and does the baking comply with the SOP requirements?', 'เมื่อชิ้นส่วน MSD เกินระยะเวลาการจัดเก็บที่กำหนด มีการอบและเป็นไปตามข้อกำหนดของ SOP หรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (43, 'SMT Line', 'SMT-General', FALSE, '確認燒錄 IC Checksum，其數值是否正確，並依要求完成打點記錄。', 'Verify the programmed IC checksum, confirm the checksum value is correct, and complete the marking record as required.', 'ตรวจสอบค่า Checksum ของ IC ที่โปรแกรมแล้วว่าถูกต้อง และมีการบันทึกการทำเครื่องหมายตามข้อกำหนดหรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (44, 'SMT Line', 'SMT-Reflow', FALSE, '回焊爐程式名稱與版本是否正確？Profile 是否與爐溫標準參數設定一致？', 'Is the reflow oven program name and version correct? Does the reflow profile comply with the standard oven temperature parameter settings?', 'ชื่อโปรแกรมและเวอร์ชันของเตารีโฟลว์ถูกต้องหรือไม่ และ Reflow Profile สอดคล้องกับค่าพารามิเตอร์อุณหภูมิมาตรฐานหรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (45, 'SMT Line', 'SMT-General', FALSE, '地面上是否乾淨？有無掉落零件？目檢台面是否擺放整潔？', 'Is the floor clean? Are there any dropped components? Is the visual inspection workstation neat and tidy?', 'พื้นที่ปฏิบัติงานสะอาดหรือไม่ มีชิ้นส่วนตกหล่นหรือไม่ และโต๊ะตรวจสอบด้วยสายตาจัดวางเป็นระเบียบหรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (46, 'SMT Line', 'SMT-General', TRUE, '零件吃錫是否在 75% 以上？', 'Is the solder coverage on the component leads greater than 75%?', 'การเปียกติดของตะกั่วบนขาชิ้นส่วนมากกว่า 75% หรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (47, 'SMT Line', 'SMT-General', TRUE, '是否有空焊、反向？COB Bonding PAD 是否有沾錫、發黃、露銅？', 'Are there any open solder joints or reversed components? Are the COB bonding pads free from solder contamination, yellowing, or exposed copper?', 'มีปัญหาบัดกรีไม่ติดหรือใส่ชิ้นส่วนกลับด้านหรือไม่ และ COB Bonding Pad ไม่มีคราบตะกั่ว สีเหลืองผิดปกติ หรือทองแดงโผล่ใช่หรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (48, 'SMT Line', 'SMT-Reflow', FALSE, 'PCB 經過回焊爐後有無掉綠漆、起泡等現象？', 'Is the PCB free from solder mask peeling, blistering, or other abnormalities after passing through the reflow oven?', 'PCB หลังผ่านเตารีโฟลว์ไม่มีการหลุดลอกของโซลเดอร์มาสก์ ฟองอากาศ หรือความผิดปกติอื่น ๆ ใช่หรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (49, 'SMT Line', 'SMT-General', FALSE, '良品和不良品是否區分、標示並隔離？', 'Are conforming and nonconforming products identified, labeled, and segregated?', 'มีการแยก ติดป้าย และกักแยกชิ้นงานดีและชิ้นงานเสียอย่างชัดเจนหรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (50, 'SMT Line', 'SMT-AOI', TRUE, 'AOI 測試是否正常？測試版本是否與實際相符？', 'Is the AOI inspection operating normally? Does the inspection program version match the actual production version?', 'การตรวจสอบด้วย AOI ทำงานเป็นปกติหรือไม่ และเวอร์ชันโปรแกรมตรวจสอบตรงกับการผลิตจริงหรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (51, 'SMT Line', 'SMT-Printer', FALSE, '鋼網放置區是否與各廠鋼網一覽表編號相符？', 'Does the stencil storage area correspond to the stencil identification list for each factory?', 'พื้นที่จัดเก็บสเตนซิลตรงกับหมายเลขในรายการสเตนซิลของแต่ละโรงงานหรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (52, 'SMT Line', 'SMT-General', FALSE, '產線是否執行 X-RAY 測試，並符合 SOP 要求？', 'Is X-RAY inspection performed on the production line in accordance with the SOP requirements?', 'สายการผลิตมีการดำเนินการตรวจสอบด้วย X-RAY และเป็นไปตามข้อกำหนดของ SOP หรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (53, 'SMT Line', 'SMT-Printer', FALSE, '報廢錫膏標示是否明確，並放置於報廢區？', 'Is the rejected solder paste clearly identified and placed in the designated scrap area?', 'ครีมบัดกรีที่ต้องทิ้งมีการติดป้ายระบุอย่างชัดเจนและจัดเก็บในพื้นที่ของเสียหรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (54, 'SMT Line', 'SMT-General', FALSE, '儲存溫濕敏元件的防潮櫃是否＜5%RH？', 'Is the dry cabinet for moisture-sensitive devices maintained below 5% RH?', 'ตู้ควบคุมความชื้นสำหรับจัดเก็บชิ้นส่วนไวต่อความชื้นควบคุมความชื้นต่ำกว่า 5%RH หรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (55, 'SMT Line', 'SMT-General', FALSE, '所有需要校驗的儀器是否已校驗？校驗是否逾期？', 'Have all instruments requiring calibration been calibrated, and are any calibrations overdue?', 'เครื่องมือที่ต้องสอบเทียบได้รับการสอบเทียบครบถ้วนหรือไม่ และมีเครื่องมือใดที่เกินกำหนดการสอบเทียบหรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (56, 'SMT Line', 'SMT-General', FALSE, '各機台是否已校正？保養點檢表是否懸掛於對應機台？', 'Has each machine been calibrated, and is the maintenance inspection checklist posted on the corresponding machine?', 'เครื่องจักรแต่ละเครื่องได้รับการปรับเทียบแล้วหรือไม่ และมีการแขวนแบบตรวจเช็กการบำรุงรักษาไว้ที่เครื่องจักรที่เกี่ยวข้องหรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (57, 'SMT Line', 'SMT-IPR', FALSE, 'IPR 烙鐵及熱風槍溫度是否有點檢？', 'Are the soldering iron and hot air gun temperatures in the IPR area inspected and recorded?', 'มีการตรวจสอบและบันทึกอุณหภูมิของหัวแร้งและเครื่องเป่าลมร้อนในพื้นที่ IPR หรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (58, 'SMT Line', 'IPR', FALSE, 'PCBA 是否有堆疊現象？', 'Is there any stacking of PCBAs?', 'มีการวางซ้อนของ PCBA หรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (59, 'SMT Line', 'SMT-IPR', FALSE, 'IPR 領用物料是否有貼 SFC 標籤？', 'Are SFC labels attached to the materials issued for IPR?', 'วัสดุที่เบิกใช้ใน IPR มีการติดฉลาก SFC หรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (60, 'SMT Line', 'SMT-IPR', FALSE, 'IPR 作業是否與 SOP 相符？', 'Are IPR operations performed in accordance with the SOP?', 'การปฏิบัติงาน IPR เป็นไปตาม SOP หรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (61, 'SMT Line', 'SMT-General', FALSE, '更換材料是否有錄入 SFC 系統？', 'Are material replacements recorded in the SFC system?', 'มีการบันทึกการเปลี่ยนวัสดุเข้าสู่ระบบ SFC หรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (62, 'SMT Line', 'SMT-IPR', FALSE, 'IPR 維修現象是否錄入 SFC？', 'Are IPR repair records entered into the SFC system?', 'มีการบันทึกข้อมูลการซ่อมของ IPR ลงในระบบ SFC หรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (63, 'SMT Line', 'Underfill-Clean', TRUE, '清洗藥水型號、配比、更換時間及超音波頻率是否正確？', 'Are the cleaning solution model, mixing ratio, replacement interval, and ultrasonic frequency correct?', 'รุ่น น้ำยาทำความสะอาด อัตราส่วนผสม รอบเวลาการเปลี่ยน และความถี่ของเครื่องอัลตราโซนิกถูกต้องหรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (64, 'SMT Line', 'SMT-General', TRUE, '清洗氣壓、時間及水流量設定是否正確？', 'Are the cleaning air pressure, cleaning time, and water flow rate settings correct?', 'การตั้งค่าแรงดันลม เวลาทำความสะอาด และอัตราการไหลของน้ำถูกต้องหรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (65, 'SMT Line', 'SMT-General', FALSE, '清洗藥水及清洗用水更換頻率是否正確？', 'Is the replacement frequency of the cleaning solution and cleaning water correct?', 'ความถี่ในการเปลี่ยนน้ำยาทำความสะอาดและน้ำล้างถูกต้องหรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (66, 'SMT Line', 'SMT-General', TRUE, '清洗後風乾及烘烤條件是否正確？', 'Are the air-drying and baking conditions after cleaning correct?', 'เงื่อนไขการเป่าแห้งและการอบหลังการทำความสะอาดถูกต้องหรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (67, 'SMT Line', 'SMT-General', TRUE, '所用膠型是否與 SOP 相符，是否超過有效期？', 'Does the adhesive type conform to the SOP, and is it within its validity period?', 'ชนิดของกาวที่ใช้งานเป็นไปตาม SOP และยังไม่เกินอายุการใช้งานหรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (68, 'SMT Line', 'SMT-General', FALSE, '點膠氣壓與針頭確認是否符合 SOP？', 'Do the dispensing air pressure and needle specification comply with the SOP?', 'แรงดันลมสำหรับการหยอดกาวและขนาด/ชนิดของเข็มหยอดกาวเป็นไปตาม SOP หรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (69, 'SMT Line', 'SMT-General', TRUE, '烤箱溫度／時間是否正確？', 'Are the oven temperature and baking time correct?', 'อุณหภูมิและเวลาในการอบถูกต้องหรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (70, 'SMT Line', 'Others', FALSE, '各站作業是否與 SOP 相符？', 'Are the operations at each workstation performed in accordance with the SOP?', 'การปฏิบัติงานในแต่ละสถานีเป็นไปตาม SOP หรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (71, 'SMT Line', 'SMT-General', FALSE, '檢查各點檢表是否依要求記錄。', 'Check whether all inspection checklists are completed and recorded as required.', 'ตรวจสอบว่าแบบฟอร์มการตรวจสอบทั้งหมดมีการบันทึกตามข้อกำหนดหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (72, 'SMT Line', 'SMT-General', FALSE, '出貨包裝箱是否有靜電蓋、靜電棉或其他防塵、防靜電保護材料？', 'Are the shipping cartons provided with an ESD cover, ESD foam, or other anti-static and dust-proof protective materials?', 'กล่องบรรจุภัณฑ์สำหรับการจัดส่งมีฝาครอบป้องกันไฟฟ้าสถิต โฟม ESD หรือวัสดุป้องกันฝุ่นและไฟฟ้าสถิตอื่น ๆ หรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (73, 'SMT Line', 'SMT-General', FALSE, '作業員是否配戴上崗認證，並依 SOP 作業？', 'Are operators wearing their work authorization certification and performing operations in accordance with the SOP?', 'พนักงานสวมบัตรหรือเครื่องหมายรับรองการปฏิบัติงาน และปฏิบัติงานตาม SOP หรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (74, 'SMT Line', 'SMT-General', FALSE, '車間及物料區 6S 管理是否落實？', 'Is 6S management effectively implemented in the workshop and material storage area?', 'มีการดำเนินการจัดการ 6S ในพื้นที่การผลิตและพื้นที่จัดเก็บวัสดุอย่างมีประสิทธิผลหรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (75, 'SMT Line', 'SMT-General', FALSE, '程式密碼管制是否正確？', 'Is the program password control properly managed?', 'การควบคุมรหัสผ่านของโปรแกรมเป็นไปตามข้อกำหนดหรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (101, 'SMT Line', 'SFC', FALSE, '工令的確認，系統內建立的工令需與生管的工令一致（工令、機種、料號、計劃數、工藝路線等）。', 'Verify that the work order created in the system is consistent with the production control work order (work order, model, part number, planned quantity, process routing, etc.).', 'ตรวจสอบว่าคำสั่งผลิตที่สร้างในระบบสอดคล้องกับคำสั่งผลิตของฝ่ายวางแผนการผลิต (หมายเลขคำสั่งผลิต รุ่น รหัสวัสดุ จำนวนตามแผน และเส้นทางกระบวนการผลิต เป็นต้น)') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (102, 'SMT Line', 'SFC', FALSE, '上料站必須先上料，再開 MOUNTING 站的自動掃描站，並核對機種的一致性。', 'At the loading station, materials shall be loaded before enabling the automatic scanning function at the mounting station, and the model shall be verified for consistency.', 'สถานีโหลดวัสดุต้องโหลดวัสดุก่อน จากนั้นจึงเปิดการสแกนอัตโนมัติของสถานี Mounting และตรวจสอบว่ารุ่นผลิตตรงกัน') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (103, 'SMT Line', 'SFC', FALSE, '稽核員工有無資格操作此站。', 'Verify whether the operator is qualified to operate the workstation.', 'ตรวจสอบว่าพนักงานมีคุณสมบัติหรือได้รับการรับรองให้ปฏิบัติงานในสถานีนี้หรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (104, 'SMT Line', 'SFC', FALSE, '所有站別員工在操作時，系統錄入工號及姓名是否與實際員工吻合。', 'Verify that the employee ID and name recorded in the system match the actual operator at each workstation.', 'ตรวจสอบว่ารหัสพนักงานและชื่อที่บันทึกในระบบตรงกับผู้ปฏิบัติงานจริงในแต่ละสถานี') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (105, 'SMT Line', 'SFC', FALSE, 'Label Link 站掃描時，需按從左至右、從上至下的順序掃描。', 'At the Label Link station, barcodes shall be scanned from left to right and from top to bottom.', 'ที่สถานี Label Link ต้องสแกนบาร์โค้ดตามลำดับจากซ้ายไปขวา และจากบนลงล่าง') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (106, 'SMT Line', 'SFC', FALSE, '管控 PCB BOX ID 的先進先出，確實要求作業員需拆一包掃一包。', 'Control PCB BOX ID using the FIFO principle. Operators shall open and scan one package at a time.', 'ควบคุมการใช้ PCB BOX ID ตามหลัก FIFO โดยกำหนดให้พนักงานเปิดและสแกนทีละ 1 แพ็ก') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (107, 'SMT Line', 'SFC', FALSE, '上料站在上料時，操機員需使用同一 Lot 依先進先出方式上料，同一 Lot 使用完後再使用下一個 Lot。', 'At the loading station, operators shall load materials using the FIFO principle within the same lot. The current lot shall be completely used before the next lot is used.', 'ที่สถานีโหลดวัสดุ ผู้ปฏิบัติงานต้องใช้วัสดุ Lot เดียวกันตามหลัก FIFO และต้องใช้ Lot เดิมให้หมดก่อนจึงเปลี่ยนไปใช้ Lot ถัดไป') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (108, 'SMT Line', 'SFC', FALSE, '檢查所有材料必須貼有 SFC 條碼與 BOX ID 條碼，每連片必須貼有主條碼。', 'Verify that all materials are labeled with SFC and BOX ID barcodes, and that each panel has a master barcode attached.', 'ตรวจสอบว่าวัสดุทั้งหมดติดบาร์โค้ด SFC และ BOX ID และทุกแผง (Panel) ต้องติดบาร์โค้ดหลัก') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (109, 'SMT Line', 'SFC', FALSE, '確認 BOM 版本是否與產線紙本料序表版本一致，且與系統料序表一致。', 'Verify that the BOM revision matches the hardcopy material list on the production line and the material list in the system.', 'ตรวจสอบว่าเวอร์ชันของ BOM ตรงกับรายการวัสดุฉบับกระดาษที่สายการผลิตและข้อมูลในระบบ') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (110, 'SMT Line', 'SFC', FALSE, 'Mounting 站自動掃描進板，不可手動推板；目檢錫膏時不可將 PCB 拿離軌道。', 'The mounting station shall automatically scan incoming boards. Manual board feeding is prohibited. During solder paste inspection, the PCB shall not be removed from the conveyor rail.', 'สถานี Mounting ต้องสแกนบอร์ดอัตโนมัติ ห้ามป้อนบอร์ดด้วยมือ และระหว่างตรวจสอบครีมบัดกรี ห้ามยก PCB ออกจากรางลำเลียง') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (111, 'SMT Line', 'SFC', FALSE, '確認鋼網／錫膏必須貼有 SFC 條碼，並於上線時掃描條碼；每次添加錫膏時需重新掃描條碼。', 'Verify that the stencil and solder paste are labeled with SFC barcodes. The barcode shall be scanned before production starts, and rescanned each time solder paste is replenished.', 'ตรวจสอบว่าสเตนซิลและครีมบัดกรีติดบาร์โค้ด SFC และต้องสแกนก่อนเริ่มการผลิต รวมถึงสแกนใหม่ทุกครั้งที่เติมครีมบัดกรี') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (112, 'SMT Line', 'SFC', FALSE, 'Underfill 膠、矽膠（TES322）必須貼有 SFC 條碼，更換時必須重新掃描條碼。', 'Underfill adhesive and silicone (TES322) shall be labeled with SFC barcodes. The barcode shall be rescanned whenever the material is replaced.', 'กาว Underfill และซิลิโคน (TES322) ต้องติดบาร์โค้ด SFC และต้องสแกนใหม่ทุกครั้งที่มีการเปลี่ยนวัสดุ') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (113, 'SMT Line', 'SFC', FALSE, '在生產打「X」板時是否有錄入「X」板條碼。', 'Verify that the barcode of the rejected ("X") board is entered into the system during production.', 'เมื่อตีเครื่องหมาย "X" บนแผงงานระหว่างการผลิต มีการบันทึกบาร์โค้ดของแผง "X" เข้าสู่ระบบหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (114, 'SMT Line', 'SFC', FALSE, '所有站別發現不良時是否有及時將條碼掃入系統。', 'Verify that defective product barcodes are scanned into the system immediately upon detection at each workstation.', 'เมื่อพบชิ้นงานเสียในแต่ละสถานี มีการสแกนบาร์โค้ดเข้าสู่ระบบทันทีหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (115, 'SMT Line', 'SFC', FALSE, 'IPR是否将所有不良录入系统 IPR 是否將所有不良錄入系統。', 'Verify that all defects are recorded in the system by IPR.', 'IPR มีการบันทึกข้อมูลชิ้นงานเสียทั้งหมดเข้าสู่ระบบหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (116, 'SMT Line', 'SFC', FALSE, 'IPR維修換料時,必須重新刷入材料條碼再更換. IPR 維修換料時，必須重新刷入材料條碼再更換。', 'During IPR repair and material replacement, the material barcode shall be rescanned before replacement.', 'เมื่อ IPR เปลี่ยนวัสดุระหว่างการซ่อม ต้องสแกนบาร์โค้ดวัสดุใหม่ก่อนทำการเปลี่ยน') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (117, 'SMT Line', 'SFC', FALSE, '在檢查站隨機抽查 1 Panel 掃入 SN，確認是否已完成各站掃描。', 'Randomly select one panel at the inspection station and scan its serial number to verify that all required workstation scans have been completed.', 'สุ่มตรวจ 1 Panel ที่สถานีตรวจสอบ โดยสแกนหมายเลข SN เพื่อตรวจสอบว่าผ่านการสแกนครบทุกสถานีแล้วหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (118, 'SMT Line', 'SFC', FALSE, '產線製程是否符合 SOP Flow Chart 規定的標準製程。', 'Does the production process comply with the standard process specified in the SOP flow chart?', 'กระบวนการผลิตในสายการผลิตเป็นไปตามกระบวนการมาตรฐานที่กำหนดไว้ในแผนผังการไหลของ SOP หรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (201, 'SMT Line', 'Laser-Marking', FALSE, '鐳雕機種程式名稱是否與 SOP 一致？', 'Is the laser marking program name for the model consistent with the SOP?', 'ชื่อโปรแกรมของเครื่องเลเซอร์มาร์กสำหรับรุ่นผลิตตรงตาม SOP หรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (202, 'SMT Line', 'Laser-Marking', FALSE, '鐳雕機種工令、批量是否有錄入系統？', 'Are the laser marking work order and production quantity entered into the system?', 'มีการบันทึกคำสั่งผลิตและจำนวนการผลิตของงานเลเซอร์มาร์กเข้าสู่ระบบหรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (203, 'SMT Line', 'Laser-Marking', FALSE, '鐳雕編碼原則是否與 SOP 一致？', 'Does the laser marking coding rule comply with the SOP?', 'หลักการกำหนดรหัสสำหรับเลเซอร์มาร์กเป็นไปตาม SOP หรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (204, 'SMT Line', 'Laser-Marking', FALSE, '鐳雕碼掃描時是否有偏移、模糊等不良？', 'Is the laser marking code free from defects such as misalignment or blurred marking during scanning?', 'รหัสเลเซอร์มาร์กไม่มีข้อบกพร่อง เช่น ตำแหน่งคลาดเคลื่อน หรือรอยพิมพ์ไม่ชัด ระหว่างการสแกนใช่หรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (205, 'SMT Line', 'Laser-Marking', FALSE, '鐳雕設備是否有落實點檢？', 'Is routine inspection carried out for the laser marking equipment?', 'มีการดำเนินการตรวจเช็กเครื่องเลเซอร์มาร์กตามข้อกำหนดหรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (206, 'SMT Line', 'Laser-Marking', FALSE, '鐳雕等級是否符合 SOP 要求？', 'Does the laser marking quality grade comply with the SOP requirements?', 'ระดับคุณภาพของการเลเซอร์มาร์กเป็นไปตามข้อกำหนดของ SOP หรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (207, 'SMT Line', 'Baking-Dry', FALSE, 'FPC 是否按照每包進行拆包烘烤／登記記錄？', 'Is each FPC package unpacked, baked, and recorded individually?', 'FPC มีการแกะบรรจุภัณฑ์ อบ และบันทึกข้อมูลแยกตามแต่ละแพ็กหรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (208, 'SMT Line', 'Baking-Dry', FALSE, 'FPC 烘烤溫度是否與 SOP 一致？', 'Is the FPC baking temperature consistent with the SOP?', 'อุณหภูมิการอบ FPC เป็นไปตาม SOP หรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (209, 'SMT Line', 'Baking-Dry', FALSE, '烘烤完成後未上線是否有放入乾燥櫃？', 'Are baked materials placed in a dry cabinet if they are not immediately released to production?', 'หลังการอบ หากยังไม่นำเข้าการผลิต มีการนำวัสดุเก็บไว้ในตู้ควบคุมความชื้นหรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (210, 'SMT Line', 'Baking-Dry', FALSE, '乾燥櫃溫濕度是否與 SOP 一致？', 'Are the temperature and humidity of the dry cabinet consistent with the SOP?', 'อุณหภูมิและความชื้นของตู้ควบคุมความชื้นเป็นไปตาม SOP หรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (211, 'SMT Line', 'Baking-Dry', FALSE, '烤箱是否有落實點檢？', 'Is routine inspection carried out for the oven?', 'มีการดำเนินการตรวจเช็กเตาอบตามข้อกำหนดหรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (212, 'SMT Line', 'IC-Programming', FALSE, '確認燒錄登記機種、料號、描述、工令、數量是否正確。', 'Verify that the programmed model, part number, description, work order, and quantity are correctly recorded.', 'ตรวจสอบว่าการบันทึกข้อมูลการโปรแกรม ได้แก่ รุ่น รหัสวัสดุ รายละเอียด คำสั่งผลิต และจำนวน ถูกต้องหรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (213, 'SMT Line', 'IC-Programming', FALSE, '確認燒錄程式版本及 Checksum 值是否正確。', 'Verify that the programming software version and checksum value are correct.', 'ตรวจสอบว่าเวอร์ชันของโปรแกรมและค่า Checksum ถูกต้องหรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (214, 'SMT Line', 'IC-Programming', FALSE, '確認燒錄後是否有做標記，IC 腳是否有變形、翹腳。', 'Verify that the programmed IC is properly marked and that there are no deformed or lifted IC leads.', 'ตรวจสอบว่าหลังการโปรแกรมมีการทำเครื่องหมาย และขา IC ไม่มีการบิดงอหรือยกตัวหรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (215, 'SMT Line', 'IC-Programming', FALSE, '燒錄完成後是否有貼溫濕敏標籤及散料跟蹤標籤？', 'Are moisture-sensitive labels and loose material tracking labels attached after programming?', 'หลังการโปรแกรม มีการติดฉลากชิ้นส่วนไวต่อความชื้นและฉลากติดตามวัสดุคงเหลือหรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (216, 'SMT Line', 'IC-Programming', FALSE, '燒錄完成後未發到產線的材料是否有放入乾燥櫃？', 'Are programmed materials that have not yet been issued to the production line stored in a dry cabinet?', 'วัสดุที่โปรแกรมเสร็จแล้วแต่ยังไม่ส่งเข้าสายการผลิต มีการจัดเก็บไว้ในตู้ควบคุมความชื้นหรือไม่?') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (1, 'DIP Line', 'DIP-General', FALSE, '.ESD监控系统是否正常运行?', 'Is the ESD Monitoring System Operating Properly?', 'ระบบตรวจติดตาม ESD ทำงานเป็นปกติหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (2, 'DIP Line', 'DIP-General', FALSE, '所有设备是否接地并贴附ESD标识标签', 'Are All Equipment Properly Grounded and Labeled with ESD Identification?', 'อุปกรณ์ทั้งหมดมีการต่อสายดินและติดป้ายระบุ ESD หรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (3, 'DIP Line', 'DIP-General', FALSE, '各站人員是否有穿静电衣,静电鞋,戴静电帽,靜電 環,静电手套作業', 'Are Operators at All Stations Wearing ESD Garments, ESD Shoes, ESD Caps, Wrist Straps, and ESD Gloves?', 'พนักงานทุกสถานีสวมชุดป้องกันไฟฟ้าสถิต รองเท้าป้องกันไฟฟ้าสถิต หมวกป้องกันไฟฟ้าสถิต สายรัดข้อมือ ESD และถุงมือ ESD ระหว่างปฏิบัติงานหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (4, 'DIP Line', 'DIP-General', FALSE, '台面,台桌,靜電椅.靜電架是否有接地', 'Are the Workbench, Worktable, ESD Chair, and ESD Rack Properly Grounded?', 'โต๊ะปฏิบัติงาน โต๊ะทำงาน เก้าอี้ ESD และชั้นวาง ESD มีการต่อสายดินอย่างถูกต้องหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (5, 'DIP Line', 'DIP-General', FALSE, 'ESD日常點檢是否有記錄?', 'Are Daily ESD Inspection Records Maintained?', 'มีการบันทึกผลการตรวจสอบ ESD ประจำวันหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (6, 'DIP Line', 'DIP-Insertion', FALSE, '材料上線前IQC是否有OK標示', 'Are Materials Marked "OK" by IQC Before Line Feeding?', 'วัสดุได้รับการระบุสถานะ OK จาก IQC ก่อนนำขึ้นสายการผลิตหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (7, 'DIP Line', 'DIP-Insertion', FALSE, '元件是否與BOM相符', 'Do the Components Match the BOM?', 'ชิ้นส่วนตรงตาม BOM หรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (8, 'DIP Line', 'DIP-Insertion', FALSE, 'PCB不可有破損.劃傷等不良現象', 'The PCB Shall Be Free from Damage, Scratches, or Other Defects.', 'แผง PCB ต้องไม่มีความเสียหาย รอยขีดข่วน หรือข้อบกพร่องอื่น ๆ') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (9, 'DIP Line', 'DIP-Insertion', TRUE, '是否有錯漏,浮高,反向現象', 'Are There Any Wrong, Missing, Lifted, or Reversed Components?', 'มีชิ้นส่วนใส่ผิด ขาด ลอยสูง หรือกลับด้านหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (10, 'DIP Line', 'DIP-Insertion', FALSE, '所有零件腳是否插入機板孔內', 'Are All Component Leads Inserted into the PCB Holes?', 'ขาชิ้นส่วนทั้งหมดเสียบเข้ารูของแผง PCB ครบถ้วนหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (11, 'DIP Line', 'DIP-Insertion', FALSE, '目視站是否有做記綠', 'Are Visual Inspection Records Maintained?', 'มีการบันทึกผลการตรวจสอบด้วยสายตาหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (12, 'DIP Line', 'DIP-Wave', FALSE, '錫爐參數是否与SOP标准相符(氣壓,流量,輸送帶速度)?', 'Are the Wave Soldering Parameters (Air Pressure, Flux Flow Rate, and Conveyor Speed) in Compliance with the SOP Requirements?', 'พารามิเตอร์ของเครื่องบัดกรีแบบเวฟ (แรงดันลม อัตราการไหลของฟลักซ์ และความเร็วสายพานลำเลียง) เป็นไปตามข้อกำหนดของ SOP หรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (13, 'DIP Line', 'DIP-Wave', FALSE, 'Profile是否有量測並經工程師签名確認.', 'Has the Profile Been Measured and Verified with the Engineer''s Signature?', 'มีการวัดค่าโปรไฟล์และได้รับการยืนยันพร้อมลายเซ็นของวิศวกรหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (14, 'DIP Line', 'DIP-Wave', FALSE, '錫棒添加是否有做記錄?', 'Is Solder Bar Replenishment Recorded?', 'มีการบันทึกการเติมแท่งบัดกรีหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (15, 'DIP Line', 'DIP-Wave', FALSE, '錫渣是否按時清理並有記錄?', 'Is Solder Dross Removed on Schedule and Recorded?', 'มีการกำจัดขี้ตะกรันบัดกรีตามกำหนดและบันทึกไว้หรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (16, 'DIP Line', 'DIP-Wave', FALSE, '噴嘴是否按要求清潔?', 'Is the Nozzle Cleaned According to the Requirements?', 'หัวฉีดได้รับการทำความสะอาดตามข้อกำหนดหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (17, 'DIP Line', 'DIP-Wave', FALSE, '噴霧均勻度工程是否有點檢?', 'Has Engineering Performed the Spray Uniformity Inspection?', 'วิศวกรได้ดำเนินการตรวจสอบความสม่ำเสมอของการพ่นแล้วหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (18, 'DIP Line', 'DIP-Wave', FALSE, 'Flux喷雾是否称重？并符合SOP规定要求？', 'Is the Flux Spray Weight Measured and Does It Meet the SOP Requirements?', 'มีการชั่งน้ำหนักปริมาณการพ่นฟลักซ์ และเป็นไปตามข้อกำหนดของ SOP หรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (19, 'DIP Line', 'DIP-Wave', FALSE, '波峰焊风扇是否正常运转并点检记录？', 'Is the Wave Soldering Fan Operating Normally and Are Inspection Records Maintained?', 'พัดลมของเครื่องบัดกรีแบบเวฟทำงานเป็นปกติ และมีการบันทึกผลการตรวจสอบหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (20, 'DIP Line', 'Assembly', FALSE, '电批是否有点检？', 'Has the Electric Screwdriver Been Inspected?', 'มีการตรวจสอบไขควงไฟฟ้าตามรอบหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (21, 'DIP Line', 'Assembly', FALSE, '螺丝是否锁到位', 'Are All Screws Properly Tightened?', 'สกรูทุกตัวขันแน่นและอยู่ในตำแหน่งที่ถูกต้องหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (22, 'DIP Line', 'Assembly', FALSE, 'PCB是否有损伤', 'Is the PCB Free from Damage?', 'แผง PCB ไม่มีความเสียหายใช่หรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (23, 'DIP Line', 'Assembly', FALSE, '元件PIN脚高度是否符合SOP標准', 'Does the Component Lead Height Comply with the SOP Requirements?', 'ความสูงของขาชิ้นส่วนเป็นไปตามมาตรฐานของ SOP หรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (24, 'DIP Line', 'DIP-Visual', TRUE, '.是否有浮高、短路、空焊、包焊、錫尖、等現象', 'Are There Any Lifted Components, Short Circuits, Open Solder Joints, Solder Encapsulation, or Solder Spikes?', 'มีชิ้นส่วนลอยสูง ลัดวงจร บัดกรีไม่ติด บัดกรีหุ้ม หรือปลายตะกั่วแหลมหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (25, 'DIP Line', 'DIP-Visual', FALSE, '各工作站作业是否与SOP相符.', 'Are All Workstations Operating in Compliance with the SOP?', 'การปฏิบัติงานของทุกสถานีเป็นไปตาม SOP หรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (26, 'DIP Line', 'DIP-Visual', TRUE, '是否有缺件.反.錯件.浮高.短路.包焊.錫尖現象', 'Are There Any Missing, Reversed, Incorrect, Lifted Components, Short Circuits, Solder Encapsulation, or Solder Spikes?', 'มีชิ้นส่วนขาด กลับด้าน ผิดตำแหน่ง ลอยสูง ลัดวงจร บัดกรีหุ้ม หรือปลายตะกั่วแหลมหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (27, 'DIP Line', 'DIP-Visual', FALSE, '吃錫是否在75%以上.', 'Is the Through-hole Solder Fill at Least 75%?', 'การเติมตะกั่วในรูขาชิ้นส่วนไม่น้อยกว่า 75% หรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (28, 'DIP Line', 'DIP-Visual', FALSE, '是否有PCB板翹現象', 'Is the PCB Free from Warpage?', 'แผง PCB ไม่มีการโก่งงอหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (29, 'DIP Line', 'DIP-Visual', FALSE, '錫絲是否為 無鉛/無鹵', 'Is the Solder Wire Lead-free / Halogen-free?', 'ลวดบัดกรีเป็นชนิดปลอดสารตะกั่ว / ปลอดฮาโลเจนหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (30, 'DIP Line', 'DIP-Visual', FALSE, '螺孔是否有吃錫', 'Are the Screw Holes Free from Solder?', 'รูยึดสกรูไม่มีตะกั่วติดค้างใช่หรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (31, 'DIP Line', 'DIP-Visual', FALSE, 'PCB及元件Mark是否清楚', 'Are the PCB and Component Markings Clear?', 'เครื่องหมายบน PCB และชิ้นส่วนมีความชัดเจนหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (32, 'DIP Line', 'DIP-Visual', FALSE, '線產品有無堆積', 'Is There Any Product Accumulation on the Production Line?', 'มีการสะสมของชิ้นงานบนสายการผลิตหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (33, 'DIP Line', 'DIP-Visual', FALSE, '所用烙铁温度是否有点检并符合SOP要求.', 'Is the Soldering Iron Temperature Inspected and in Compliance with the SOP Requirements?', 'มีการตรวจสอบอุณหภูมิหัวแร้งและเป็นไปตามข้อกำหนดของ SOP หรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (34, 'DIP Line', 'DIP-Visual', FALSE, '目視站是否有做記綠/目視站是否有使用放大鏡?', 'Are Visual Inspection Records Maintained, and Is a Magnifier Used at the Visual Inspection Station?', 'มีการบันทึกผลการตรวจสอบด้วยสายตา และมีการใช้แว่นขยายในสถานีตรวจสอบด้วยสายตาหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (35, 'DIP Line', 'DIP-Visual', FALSE, '產線是否清潔', 'Is the Production Line Clean?', 'สายการผลิตมีความสะอาดหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (36, 'DIP Line', 'DIP-Visual', FALSE, '線路是否劃傷', 'Are the PCB Circuit Traces Free from Scratches?', 'ลายวงจรบน PCB ไม่มีรอยขีดข่วนหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (37, 'DIP Line', 'DIP-Visual', FALSE, 'PCB是否有起泡現象', 'Is the PCB Free from Blistering?', 'แผง PCB ไม่มีการพองหรือเกิดฟองใช่หรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (38, 'DIP Line', 'DIP-Visual', FALSE, '元件是否破損', 'Are the Components Free from Damage?', 'ชิ้นส่วนไม่มีความเสียหายใช่หรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (39, 'DIP Line', 'DIP-General', FALSE, 'ICT测试程式是否与SOP相符？', 'Is the ICT Test Program in Compliance with the SOP?', 'โปรแกรมทดสอบ ICT เป็นไปตาม SOP หรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (40, 'DIP Line', 'DIP-General', FALSE, 'ICT測試探針的使用壽命是否超過SOP規定的壽命次數?', 'Has the Service Life of the ICT Test Probes Exceeded the Limit Specified in the SOP?', 'อายุการใช้งานของเข็มทดสอบ ICT เกินจำนวนครั้งที่กำหนดไว้ใน SOP หรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (41, 'DIP Line', 'DIP-General', FALSE, 'ICT探針是否有按要求清潔?', 'Are the ICT Test Probes Cleaned According to the Requirements?', 'เข็มทดสอบ ICT ได้รับการทำความสะอาดตามข้อกำหนดหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (42, 'DIP Line', 'DIP-General', FALSE, 'ICT是否有日常點檢記錄', 'Are Daily ICT Inspection Records Maintained?', 'มีการบันทึกการตรวจสอบ ICT ประจำวันหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (43, 'DIP Line', 'DIP-General', FALSE, '工程是否进行Go-No /Go Sample点检？', 'Has Engineering Performed the Go/No-Go Sample Inspection?', 'วิศวกรได้ดำเนินการตรวจสอบตัวอย่างแบบ Go/No-Go แล้วหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (44, 'DIP Line', 'DIP-General', FALSE, 'FCT測試程式與版本是否與sop相符？', 'Are the FCT Test Program and Version in Compliance with the SOP?', 'โปรแกรมและเวอร์ชันของการทดสอบ FCT เป็นไปตาม SOP หรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (45, 'DIP Line', 'DIP-General', FALSE, '测试站位是否进行Go-No /Go Sample点检？', 'Has the Test Station Performed the Go/No-Go Sample Inspection?', 'สถานีทดสอบได้ดำเนินการตรวจสอบตัวอย่างแบบ Go/No-Go แล้วหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (46, 'DIP Line', 'DIP-General', FALSE, '測試動作是否與SOP相符?', 'Are the Test Procedures in Compliance with the SOP?', 'ขั้นตอนการทดสอบเป็นไปตาม SOP หรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (47, 'DIP Line', 'Programming', FALSE, '烧錄版本是否与SOP相符？', 'Is the Programming Version in Compliance with the SOP?', 'เวอร์ชันการโปรแกรมเป็นไปตาม SOP หรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (48, 'DIP Line', 'Programming', FALSE, 'Check Checksum值多少?', 'Verify the Checksum Value.', 'ตรวจสอบค่า Checksum') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (49, 'DIP Line', 'Programming', FALSE, 'check SFC系統版本是否為最新版本?', 'Verify That the SFC System Version Is the Latest Version.', 'ตรวจสอบว่าเวอร์ชันของระบบ SFC เป็นเวอร์ชันล่าสุดหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (50, 'DIP Line', 'Depaneling', FALSE, '分板参数是否与SOP相符', 'Are the Depaneling Parameters in Compliance with the SOP?', 'พารามิเตอร์การแยกแผงเป็นไปตาม SOP หรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (51, 'DIP Line', 'Depaneling', FALSE, '分板品质要求是否在SOP规定内（凹凸规格）', 'Does the Depaneling Quality Meet the SOP Requirements (Burr/Step Height Specification)?', 'คุณภาพหลังการแยกแผงเป็นไปตามข้อกำหนดของ SOP (ค่าครีบและความต่างระดับ) หรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (52, 'DIP Line', 'Depaneling', FALSE, '分板后是否进行外观检查,撞件/灰尘确认？', 'Is a Visual Inspection Performed After Depaneling to Verify Component Damage and Dust Contamination?', 'หลังการแยกแผง มีการตรวจสอบลักษณะภายนอกเพื่อยืนยันว่าไม่มีชิ้นส่วนเสียหายจากการกระแทกและไม่มีฝุ่นตกค้างหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (53, 'DIP Line', 'Depaneling', FALSE, '烙铁及热风枪温度是否有点检', 'Are the Soldering Iron and Hot Air Gun Temperatures Inspected?', 'มีการตรวจสอบอุณหภูมิของหัวแร้งและเครื่องลมร้อนหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (54, 'DIP Line', 'DIP-General', FALSE, 'PCBA是否堆疊現象?', 'Is the PCBA Free from Stacking?', 'PCBA ไม่มีการวางซ้อนกันหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (55, 'DIP Line', 'DIP-General', FALSE, 'IPR領用物料是否有貼SFC標籤', 'Are the Materials Issued for IPR Labeled with SFC Labels?', 'วัสดุที่เบิกใช้สำหรับ IPR มีการติดฉลาก SFC หรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (56, 'DIP Line', 'DIP-General', FALSE, '維修品經IPQC抽查是否OK?', 'Do the Repaired Products Pass IPQC Sampling Inspection?', 'ชิ้นงานที่ซ่อมผ่านการสุ่มตรวจของ IPQC แล้วหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (57, 'DIP Line', 'DIP-General', FALSE, 'IPR作業是否與SOP相符?', 'Are the IPR Operations in Compliance with the SOP?', 'การปฏิบัติงาน IPR เป็นไปตาม SOP หรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (58, 'DIP Line', 'DIP-General', FALSE, '更換材料是否有錄入SFC系統？', 'Are the Replaced Materials Recorded in the SFC System?', 'มีการบันทึกข้อมูลวัสดุที่เปลี่ยนลงในระบบ SFC หรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (59, 'DIP Line', 'DIP-General', FALSE, 'IPR维修现象是否录入SFC？', 'Are the IPR Repair Findings Recorded in the SFC System?', 'มีการบันทึกข้อมูลอาการเสียหรือผลการซ่อมของ IPR ลงในระบบ SFC หรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (60, 'DIP Line', 'Glue-Dispensing', FALSE, '點膠胶水型號是否與SOP相符', 'Is the Adhesive Model Used for Glue Dispensing in Compliance with the SOP?', 'รุ่นของกาวที่ใช้ในการหยอดกาวเป็นไปตาม SOP หรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (61, 'DIP Line', 'Glue-Dispensing', FALSE, '点胶路径及程式名要求是否与SOP相符？', 'Are the Glue Dispensing Path and Program Name in Compliance with the SOP?', 'เส้นทางการหยอดกาวและชื่อโปรแกรมเป็นไปตามข้อกำหนดของ SOP หรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (62, 'DIP Line', 'Glue-Dispensing', FALSE, '烤箱設定溫度&時間是否與SOP相符?', 'Are the Oven Temperature and Baking Time Settings in Compliance with the SOP?', 'การตั้งค่าอุณหภูมิและเวลาในการอบเป็นไปตาม SOP หรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (63, 'DIP Line', 'Glue-Dispensing', FALSE, '目檢站是否檢查烘烤PCBA underfill膠品質', 'Does the Visual Inspection Station Verify the Quality of the Underfill Adhesive After PCBA Baking?', 'สถานีตรวจสอบด้วยสายตามีการตรวจสอบคุณภาพของกาว Underfill หลังการอบ PCBA หรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (64, 'DIP Line', 'Environment', FALSE, '車間溫濕度是否在20-28℃,RH30%-60%之間?', 'Are the Workshop Temperature and Humidity Maintained Within 20–28°C and RH 30%–60%?', 'อุณหภูมิและความชื้นภายในพื้นที่การผลิตอยู่ในช่วง 20–28°C และ RH 30%–60% หรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (65, 'DIP Line', 'Environment', FALSE, '成品，半成品，良品，不良品,可疑品是否整齊擺放於相應位置？且有明显标示?', 'Are Finished Products, Semi-finished Products, Good Products, Defective Products, and Suspected Products Properly Stored in Their Designated Locations and Clearly Identified?', 'สินค้าสำเร็จรูป ชิ้นงานกึ่งสำเร็จรูป ของดี ของเสีย และชิ้นงานต้องสงสัย จัดวางในตำแหน่งที่กำหนดอย่างเป็นระเบียบและมีป้ายระบุอย่างชัดเจนหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (66, 'DIP Line', 'Environment', FALSE, '物料是否擺放在相應位置?', 'Are the Materials Stored in Their Designated Locations?', 'วัสดุจัดวางไว้ในตำแหน่งที่กำหนดหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (67, 'DIP Line', 'Environment', FALSE, '環境是否清潔？产线是否存在产生异物的站别？', 'Is the Working Environment Clean? Are There Any Workstations That May Generate Foreign Materials on the Production Line?', 'สภาพแวดล้อมมีความสะอาดหรือไม่ และมีสถานีงานใดในสายการผลิตที่อาจก่อให้เกิดสิ่งแปลกปลอมหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (68, 'DIP Line', 'SOP-Standards', FALSE, '所有SOP是否經IE發行,並有蓋發行章', 'Have All SOPs Been Issued by IE and Stamped with the Official Issue Stamp?', 'SOP ทั้งหมดได้รับการออกเอกสารโดย IE และประทับตราออกเอกสารแล้วหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (69, 'DIP Line', 'SOP-Standards', FALSE, '臨時SOP手改超過48h是否更新？', 'Has Any Temporary Handwritten SOP Revision Exceeding 48 Hours Been Updated?', 'SOP ที่มีการแก้ไขด้วยลายมือชั่วคราวเกิน 48 ชั่วโมง ได้รับการปรับปรุงแล้วหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (70, 'DIP Line', 'SOP-Standards', FALSE, '稽查各机台所有校正，保养点检表是否悬挂于对应站位机台？', 'Are the Calibration, Maintenance, and Inspection Records for All Machines Posted at Their Corresponding Workstations?', 'แบบบันทึกการสอบเทียบ การบำรุงรักษา และการตรวจสอบของเครื่องจักรทุกเครื่อง ติดไว้ที่สถานีงานของเครื่องที่เกี่ยวข้องหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (71, 'DIP Line', 'SOP-Standards', FALSE, '治工具&PCBA外箱标签是否有Green/HF標示?', 'Are the Tooling and PCBA Carton Labels Marked with Green/HF Identification?', 'เครื่องมือ/ฟิกซ์เจอร์ และฉลากกล่องบรรจุ PCBA มีการระบุ Green/HF หรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (72, 'DIP Line', 'SOP-Standards', FALSE, '生産輔材&IPR是否Green/HF嚴格區分?', 'Are Production Auxiliary Materials and IPR Materials Strictly Segregated Between Green and HF?', 'วัสดุช่วยการผลิตและวัสดุที่ใช้ใน IPR มีการแยก Green/HF อย่างชัดเจนหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (73, 'DIP Line', 'SOP-Standards', FALSE, '生産輔材型號是否與SOP相符', 'Are the Production Auxiliary Material Specifications in Compliance with the SOP?', 'รุ่นหรือสเปกของวัสดุช่วยการผลิตเป็นไปตาม SOP หรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (74, 'DIP Line', 'Inspection & Packaging', FALSE, '检查FW/PN/SN Lable各标签是否与SOP相符', 'Verify Whether the FW/PN/SN Labels Are in Compliance with the SOP.', 'ตรวจสอบว่าฉลาก FW/PN/SN เป็นไปตาม SOP หรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (75, 'DIP Line', 'Inspection & Packaging', FALSE, '包裝箱/Tray盤是否與SOP相符？', 'Are the Packaging Cartons and Trays in Compliance with the SOP?', 'กล่องบรรจุและถาด Tray เป็นไปตาม SOP หรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (76, 'DIP Line', 'Inspection & Packaging', FALSE, '各机種标签是否正确，若为条码，是否符合编码规则？并每2小时确认5pcs).', 'Are the Labels for Each Model Correct? If Barcodes Are Used, Do They Comply with the Coding Rules? Verify 5 pcs Every 2 Hours.', 'ฉลากของแต่ละรุ่นถูกต้องหรือไม่ หากเป็นบาร์โค้ด เป็นไปตามกฎการเข้ารหัสหรือไม่ และให้ตรวจสอบ 5 ชิ้นทุก 2 ชั่วโมง') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (77, 'DIP Line', 'Inspection & Packaging', FALSE, '出货高度不可超出1.8m', 'The Shipping Stack Height Shall Not Exceed 1.8 m.', 'ความสูงในการจัดเรียงเพื่อการจัดส่งต้องไม่เกิน 1.8 เมตร') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (78, 'DIP Line', 'Inspection & Packaging', FALSE, '是否有漏裝，反裝現象？', 'Are There Any Missing or Reversed Assemblies?', 'มีการประกอบขาดหรือประกอบกลับด้านหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (79, 'DIP Line', 'DIP-General', FALSE, '所有站别员工在操作时,系统录入工号及姓名是否与实际员工吻合', 'During Operation, Do the Employee ID and Name Entered into the System Match the Actual Operator at Every Workstation?', 'ระหว่างการปฏิบัติงาน หมายเลขพนักงานและชื่อที่บันทึกในระบบตรงกับผู้ปฏิบัติงานจริงของทุกสถานีหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (80, 'DIP Line', 'DIP-General', FALSE, 'Label link站掃描時,需按從左至右, 從上至下的順序掃描', 'At the Label Link Station, Are Labels Scanned in the Sequence from Left to Right and Top to Bottom?', 'ที่สถานี Label Link มีการสแกนฉลากตามลำดับจากซ้ายไปขวา และจากบนลงล่างหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (81, 'DIP Line', 'DIP-General', FALSE, '管控PCB BOX ID的先進先出,確實要求作業員需拆一包掃一包', 'Is the FIFO Control of PCB Box IDs Implemented by Requiring Operators to Open and Scan One Box at a Time?', 'มีการควบคุม FIFO ของ PCB Box ID โดยกำหนดให้พนักงานเปิดและสแกนทีละกล่องหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (82, 'DIP Line', 'DIP-General', FALSE, '上料站,在上料時作業員需擺同一Lot進行先進先出上料,同一Lot先使用完,再使用下一個不同的Lot', 'At the Material Loading Station, Are Materials Loaded Using FIFO by Consuming the Same Lot Completely Before Using the Next Lot?', 'ที่สถานีป้อนวัสดุ มีการป้อนวัสดุตามหลัก FIFO โดยใช้วัสดุ Lot เดียวให้หมดก่อน แล้วจึงเริ่มใช้ Lot ถัดไปหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (83, 'DIP Line', 'DIP-General', FALSE, '檢查所有材料必須貼有SFC條碼與BOX ID條碼,主條碼每連片必須貼有主條碼', 'Verify That All Materials Are Labeled with SFC Barcodes and BOX ID Barcodes, and That Each PCB Panel Has the Required Master Barcode.', 'ตรวจสอบว่าวัสดุทั้งหมดติดฉลาก SFC และ BOX ID และทุกแผง PCB ต้องมีการติดฉลาก Master Barcode ตามข้อกำหนด') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (84, 'DIP Line', 'DIP-General', FALSE, 'Underfill站,在更換時必須重新掃入條碼.', 'At the Underfill Station, Is the Barcode Rescanned Whenever Material Replacement Is Performed?', 'ที่สถานี Underfill เมื่อมีการเปลี่ยนวัสดุ ต้องสแกนบาร์โค้ดใหม่ทุกครั้งหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (85, 'DIP Line', 'DIP-General', FALSE, '在生产打"X"板时是否有录入打"X"板条码.', 'When an "X" PCB Is Identified During Production, Is Its Barcode Recorded in the System?', 'เมื่อมีการทำเครื่องหมายแผง "X" ระหว่างการผลิต มีการบันทึกบาร์โค้ดของแผง "X" ลงในระบบหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (86, 'DIP Line', 'DIP-General', FALSE, '所有站别发现不良时是否有及时将条码扫入系统', 'When Defects Are Found at Any Workstation, Are the Corresponding Barcodes Scanned into the System Promptly?', 'เมื่อพบชิ้นงานไม่ดีในทุกสถานี มีการสแกนบาร์โค้ดเข้าสู่ระบบทันทีหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (87, 'DIP Line', 'DIP-General', FALSE, '稽核員工有無資格操作此站', 'Audit Whether Operators Are Qualified to Operate This Station.', 'ตรวจสอบว่าพนักงานมีคุณสมบัติในการปฏิบัติงานที่สถานีนี้หรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (88, 'DIP Line', 'DIP-General', FALSE, '電腦殺毒軟件是否正常運行', 'Is the Antivirus Software Operating Properly?', 'ซอฟต์แวร์ป้องกันไวรัสในคอมพิวเตอร์ทำงานเป็นปกติหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (89, 'DIP Line', 'DIP-General', FALSE, '所有校驗儀器是否有效期內', 'Are All Calibration Instruments Within Their Validity Period?', 'เครื่องมือสอบเทียบทั้งหมดอยู่ภายในอายุการใช้งานที่กำหนดหรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (90, 'DIP Line', 'DIP-General', FALSE, '產線制程是否符合SOP Flow Chart規定的標準制程', 'Does the Production Process Comply with the Standard Process Defined in the SOP Flow Chart?', 'กระบวนการผลิตเป็นไปตามมาตรฐานที่กำหนดในแผนผัง SOP หรือไม่') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (91, 'DIP Line', 'Q-Black-Security', FALSE, '任何接触与Q产品相关人员必须遵守Q产品相关安全保密协议条款', 'All Personnel Involved with Q Products Must Comply with the Q Product Security and Confidentiality Agreement Terms', 'บุคลากรที่เกี่ยวข้องกับผลิตภัณฑ์ Q ต้องปฏิบัติตามข้อตกลงด้านความปลอดภัยและการรักษาความลับของผลิตภัณฑ์ Q อย่างเคร่งครัด') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (92, 'DIP Line', 'Q-Black-Security', FALSE, '非Q 產品相關工作人員嚴禁進入Q產品工作區域.', 'Non-Q Product Personnel Are Strictly Prohibited from Entering the Q Product Work Area', 'บุคลากรที่ไม่เกี่ยวข้องกับผลิตภัณฑ์ Q ห้ามเข้าพื้นที่การทำงานของผลิตภัณฑ์ Q อย่างเด็ดขาด') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (93, 'DIP Line', 'Q-Black-Security', FALSE, '工作人員出入工作區域需佩帶Q產品識別卡,識別卡需要正確佩帶,卡內不得裝有其它私人物品.', 'Personnel Must Wear Q Product Identification Cards When Entering or Leaving the Work Area; Cards Must Be Properly Worn and Must Not Contain Any Personal Items', 'พนักงานต้องสวมบัตรประจำตัวผลิตภัณฑ์ Q เมื่อเข้า–ออกพื้นที่ และต้องสวมให้ถูกต้อง ห้ามใส่สิ่งของส่วนตัวในบัตร') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (94, 'DIP Line', 'Q-Black-Security', FALSE, '所有人員進出Q產品工作區域需要經過內保核實身份.並自覺接受安檢檢查.', 'All Personnel Entering or Exiting the Q Product Area Must Undergo Identity Verification by Internal Security and Accept Security Inspection', 'ทุกคนที่เข้า–ออกพื้นที่ผลิตภัณฑ์ Q ต้องผ่านการตรวจสอบตัวตนโดยเจ้าหน้าที่รักษาความปลอดภัยภายใน และยินยอมรับการตรวจความปลอดภัย') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (95, 'DIP Line', 'Q-Black-Security', FALSE, '所有人員禁止攜帶手', 'Mobile Phones, Cameras, and Portable Storage Devices Are Prohibited in the Work Area', 'ห้ามนำโทรศัพท์มือถือ กล้องถ่ายรูป และอุปกรณ์จัดเก็บข้อมูลแบบพกพาเข้าสู่พื้นที่ทำงาน機,相機,移動儲存裝置等物品進入工作區域.') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (96, 'DIP Line', 'Q-Black-Security', FALSE, 'Q產品相關工作人員不可以對外講述任何有關產品資訊.', 'Q Product Personnel Are Prohibited from Disclosing Any Product Information to External Parties', 'พนักงานที่เกี่ยวข้องกับผลิตภัณฑ์ Q ห้ามเปิดเผยข้อมูลผลิตภัณฑ์ต่อบุคคลภายนอก') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (97, 'DIP Line', 'Q-Black-Security', FALSE, '針對Q產品材料實行專門區域,專用物料箱及專人管理.', 'Q Product Materials Shall Be Managed in Dedicated Areas with Dedicated Material Boxes and Assigned Personnel', 'วัสดุของผลิตภัณฑ์ Q ต้องจัดเก็บในพื้นที่เฉพาะ ใช้กล่องวัสดุเฉพาะ และมีผู้รับผิดชอบเฉพาะ') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (98, 'DIP Line', 'Q-Black-Security', FALSE, '物料周轉過程中需要使用專用物料箱,並且需要加蓋加鎖保密.', 'Dedicated Material Boxes Must Be Used During Material Transfer and Must Be Covered and Locked for Security', 'ระหว่างการเคลื่อนย้ายวัสดุต้องใช้กล่องเฉพาะ และต้องมีฝาปิดและล็อกเพื่อรักษาความปลอดภัย') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (99, 'DIP Line', 'Q-Black-Security', FALSE, 'Q產品設立專門的工作區域並使用圍欄加密.', 'A Dedicated Q Product Work Area Shall Be Established and Secured with Fencing', 'ต้องจัดตั้งพื้นที่เฉพาะสำหรับผลิตภัณฑ์ Q และกั้นรั้วเพื่อความปลอดภัย') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (100, 'DIP Line', 'Q-Black-Security', FALSE, '產線出/入口要有明確的中英文標示.並設立專人做人員及物品的進出管制.', 'Clear Chinese and English Signage Shall Be Posted at Production Line Entry/Exit Points, with Assigned Personnel for Access and Material Control', 'จุดเข้า–ออกสายการผลิตต้องมีป้ายภาษาจีนและอังกฤษอย่างชัดเจน และมีเจ้าหน้าที่ควบคุมการเข้า–ออกของบุคลากรและวัสดุ') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (101, 'DIP Line', 'Document-Security', FALSE, 'Q產品所有文件內不允許有"客戶/機種"的名稱,統一使用Q代替.', 'All Q Product Documents Shall Not Contain Customer or Model Names; “Q” Shall Be Used as a Unified Identifier Instead', 'เอกสารทั้งหมดของผลิตภัณฑ์ Q ห้ามระบุชื่อ “ลูกค้า/รุ่นสินค้า” ให้ใช้ “Q” แทนทั้งหมด') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (102, 'DIP Line', 'Document-Security', FALSE, '文件僅限定在Q工作區域內使用不可外傳.', 'Documents Are Restricted for Use Only Within the Q Work Area and Must Not Be Disclosed or Removed Externally', 'เอกสารจำกัดการใช้งานเฉพาะในพื้นที่ทำงาน Q เท่านั้น ห้ามนำออกหรือเผยแพร่ภายนอก') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.checklist_master (item_no, process, station_tag, requires_qty, zh, en, th) VALUES (103, 'DIP Line', 'Document-Security', FALSE, '紙張文件使用後的報廢紙張需要銷毀,不能做再生紙使用.', 'Used Paper Documents Must Be Shredded and Destroyed; Reuse as Recycled Paper Is Prohibited', 'เอกสารกระดาษที่ใช้งานแล้วต้องทำลายทิ้ง ไม่อนุญาตให้นำไปใช้เป็นกระดาษรีไซเคิล') ON CONFLICT (item_no) DO NOTHING;
INSERT INTO public.capa (id, audit_id, station_code, line_name, item_no, defect_description, photo_url, severity, status, owner, due_date) VALUES ('CAPA-2026-001', 'AUD-1001', 'SMT-L1-OVEN-01', 'SMT Line 1', 70, 'Nitrogen Flow rate below 150L/min threshold', 'https://images.unsplash.com/photo-1581092160607-ee22621dd758?w=500', 'HIGH', 'OPEN', 'Norman Nan (Line Supervisor)', CURRENT_DATE + INTERVAL '2 days'), ('CAPA-2026-002', 'AUD-1002', 'SMT-L1-ESD-01', 'Global Factory', 3, 'Operator wrist strap grounding wire unclipped at Station 4', 'https://images.unsplash.com/photo-1581092335397-9583fe92d232?w=500', 'MEDIUM', 'INVESTIGATING', 'John Tan (QA Eng)', CURRENT_DATE + INTERVAL '2 days') ON CONFLICT DO NOTHING;